package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class TypeChecks {
 private GameWorld world(GameWorld.Skill move){GameWorld w=new GameWorld();w.enemies.clear();TestWorlds.equip(w,move);return w;}
 private GameWorld.Enemy target(GameWorld w,GameWorld.Element type){GameWorld.Enemy e=new GameWorld.Enemy(220,112,true);e.hp=e.maxHp=3000;e.timer=100;e.primaryType=type;w.enemies.add(e);return e;}
 private void tick(GameWorld w,int frames){for(int n=0;n<frames;n++)w.step(1f/60,0,false,false);}
 private float factor(GameWorld.Element a,GameWorld.Element d){return TypeChart.multiplier(a,d,null);}
 @Test public void allEighteenTypesHaveUniqueIdsAndCompleteChart(){boolean[] seen=new boolean[19];int zero=0;assertEquals(18,GameWorld.Element.values().length);for(GameWorld.Element a:GameWorld.Element.values()){assertTrue(a.typeId>0&&a.typeId<=18);assertFalse(seen[a.typeId]);seen[a.typeId]=true;assertTrue(a.rgb>0);for(GameWorld.Element d:GameWorld.Element.values()){float f=factor(a,d);assertTrue(f==0||f==.5f||f==1||f==2);if(f==0)zero++;}}assertEquals(8,zero);}
 @Test public void currentEnemyWeaknessesFollowChart(){assertEquals(2,factor(GameWorld.Element.FIGHTING,GameWorld.Element.NORMAL),0);assertEquals(2,factor(GameWorld.Element.GROUND,GameWorld.Element.POISON),0);assertEquals(2,factor(GameWorld.Element.PSYCHIC,GameWorld.Element.POISON),0);assertEquals(.5f,factor(GameWorld.Element.FIGHTING,GameWorld.Element.POISON),0);assertEquals(2,factor(GameWorld.Element.ROCK,GameWorld.Element.FIRE),0);assertEquals(.5f,factor(GameWorld.Element.FIRE,GameWorld.Element.FIRE),0);assertEquals(0,factor(GameWorld.Element.GHOST,GameWorld.Element.NORMAL),0);}
 @Test public void dualTypesMultiplyAndImmunityWins(){assertEquals(4,TypeChart.multiplier(GameWorld.Element.GROUND,GameWorld.Element.FIRE,GameWorld.Element.POISON),0);assertEquals(.25f,TypeChart.multiplier(GameWorld.Element.FIRE,GameWorld.Element.WATER,GameWorld.Element.DRAGON),0);assertEquals(0,TypeChart.multiplier(GameWorld.Element.ELECTRIC,GameWorld.Element.WATER,GameWorld.Element.GROUND),0);assertEquals(2,TypeChart.multiplier(GameWorld.Element.GROUND,GameWorld.Element.FIRE,GameWorld.Element.FIRE),0);}
 @Test public void monstersAndBossesReceiveSpeciesTypes(){GameWorld w=new GameWorld();assertEquals(GameWorld.Element.NORMAL,w.enemies.get(0).primaryType);assertTrue(w.enemies.stream().filter(e->e.spitter).allMatch(e->e.primaryType==GameWorld.Element.POISON));GameWorld.Element[] expected={GameWorld.Element.NORMAL,GameWorld.Element.POISON,GameWorld.Element.FIRE};for(int area=1;area<=15;area++){if(w.isBossRoom()){assertEquals(expected[w.stage-1],w.boss.primaryType);w.boss.hp=0;}if(area<15){w.stageComplete=true;assertTrue(w.advanceStage());}}}
 @Test public void actualMeleeUsesWeaknessResistanceAndEchoOnlyOnce(){GameWorld w=world(GameWorld.Skill.BRICK_BREAK);GameWorld.Enemy e=target(w,GameWorld.Element.NORMAL);int base=w.skillDamage(GameWorld.Skill.BRICK_BREAK);w.collectItem(GameWorld.Item.MULTI);w.trySkill(0);tick(w,45);int direct=e.lastDamage;assertEquals(3000-direct-Math.round(direct*.5f),e.hp);assertEquals(2,e.lastEffectiveness,0);w=world(GameWorld.Skill.BRICK_BREAK);e=target(w,GameWorld.Element.POISON);base=w.skillDamage(GameWorld.Skill.BRICK_BREAK);w.trySkill(0);tick(w,35);assertEquals(3000-w.damageAgainst(GameWorld.Skill.BRICK_BREAK,e),e.hp);}
 @Test public void fireResistanceAndBurnImmunityWorkInActualProjectile(){GameWorld w=world(GameWorld.Skill.EMBER);GameWorld.Enemy e=target(w,GameWorld.Element.FIRE);int damage=Math.round(w.skillDamage(GameWorld.Skill.EMBER)*.5f);w.trySkill(0);tick(w,80);assertEquals(3000-damage,e.hp);assertEquals(0,e.burnTime,0);assertEquals(.5f,e.lastEffectiveness,0);}
 @Test public void immuneHitsHaveNoDamageHealEchoOrStatus(){GameWorld w=world(GameWorld.Skill.SCRATCH);w.hp=2;w.collectItem(GameWorld.Item.MULTI);for(int n=0;n<6;n++)w.collectItem(GameWorld.Item.SHELL);GameWorld.Enemy e=target(w,GameWorld.Element.GHOST);w.trySkill(0);tick(w,70);assertEquals(3000,e.hp);assertEquals(2,w.hp);assertEquals(0,w.kills);assertEquals(0,e.lastDamage);assertEquals("효과 없음",e.combatNote);w=world(GameWorld.Skill.DRAGON);e=target(w,GameWorld.Element.FAIRY);w.trySkill(0);tick(w,45);assertEquals(3000,e.hp);assertEquals(0,e.slowTime,0);}
 @Test public void burnTicksUseTargetMaxHpAndStatusIsNotBlockedByDamageImmunity(){GameWorld w=world(GameWorld.Skill.GROWL);GameWorld.Enemy e=target(w,GameWorld.Element.GHOST);w.trySkill(0);tick(w,25);assertTrue(e.weakened>0);w=world(GameWorld.Skill.SCRATCH);e=target(w,GameWorld.Element.GRASS);e.burnTime=1;e.burnTick=.01f;tick(w,1);assertEquals(2880,e.hp);assertEquals(0,w.matchupDamage(0,GameWorld.Skill.EMBER,e));}
 @Test public void changingEquippedSlotKeepsTheSkillsTypeAndPalette(){GameWorld w=world(GameWorld.Skill.FIRE_PUNCH);int fire=GameWorld.Element.FIRE.rgb;TestWorlds.equip(w,GameWorld.Skill.DRAGON,GameWorld.Skill.SCRATCH,GameWorld.Skill.FIRE_PUNCH);assertEquals(fire,w.skillAt(2).element.rgb);assertEquals(0xEE8130,fire);assertEquals(0x6F35FC,w.skillAt(0).element.rgb);assertTrue(new GameWorld.Enemy(0,112,true).weaknesses().contains("땅"));}
}